const $=s=>document.querySelector(s), esc=s=>String(typeof s==='number'?new Intl.NumberFormat(getLocale(),{useGrouping:false}).format(s):(s??'')).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,evidence,chamber='senate',scene,camera,renderer,group,meshes=[],selected;
const colors={D:0x155dff,R:0xf1264f,I:0x9c54ff,U:0x7c8999,T:0xf8b82b},names={D:'民主党',R:'共和党',I:'独立',U:'待核验',T:'竞争胶着'};
const ratingLabel=r=>r?.ratingZh||({'solid-D':'民主党稳固','likely-D':'民主党优势','lean-D':'倾向民主党','tossup':'竞争胶着','lean-R':'倾向共和党','likely-R':'共和党优势','solid-R':'共和党稳固'}[r?.rating])||'暂无核验评级';
