function party(s){if(!s.contested2026)return s.currentParty||'U';let r=rate(s);return r?.rating==='tossup'?'T':r?.party||r?.leanParty||(String(r?.rating||'').endsWith('D')?'D':String(r?.rating||'').endsWith('R')?'R':'U');}
function label(s){return s.chamber==='senate'?`${s.state} · 参议院${s.special?'特别选举':''}`:`${s.state}-${s.district===0?'AL':String(s.district).padStart(2,'0')}`;}
function show(s){selected=s;$('#seat-title').textContent=label(s);const r=rate(s);$('#seat-detail').innerHTML=`<strong>${esc(s.incumbent||'现任空缺')}</strong><br>现任：${esc(names[s.currentParty]||'空缺')} ${s.caucus&&s.caucus!==s.currentParty?`（${names[s.caucus]}党团）`:''}<br>${s.contested2026?'2026 改选':'本届不改选'}${s.contested2026?`<br>机构评级：${esc(ratingLabel(r))}`:''}${s.chamber==='house'?'<details class="source-details"><summary>资料状态</summary><p>现任为第119届记录；2026评级按新选举区，不代表现任参选或选区边界不变。</p></details>':''}<br><a href="${esc(r?.source||s.source)}" target="_blank" rel="noopener">原始来源 ↗</a>`;}
