function init3D(){try{theatre=createParliament($('#canvas'),{seats:data.seats,party,rate,label,onSelect:s=>{show(s);openProfile(s);},changes:evidence.ratingChanges,evidence,leadership:leadershipData,onLeader:showLeader});sceneStats();table();}catch(e){$('#canvas').dataset.renderError=e.message;fallback();table();document.querySelectorAll('.scene-controls button').forEach(b=>b.disabled=true);$('.model-caption').textContent='2D 兼容模式 / 当前浏览器未启用 WebGL';$('#scene-status').textContent='3D 相机功能需浏览器支持 WebGL';}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));theatre?.setMode(b.dataset.view);$('#scene-status').textContent=b.dataset.view==='current'?'现任党籍配色 · 不改变实际/示意座位':b.dataset.view==='changes'?'来源已记录评级变更的席位以金色光环标记':'虚影为改选席 · 颜色为来源评级类别，非胜率';});$('#scene-reset').onclick=()=>theatre?.reset();$('#scene-exterior').onclick=()=>theatre?.exterior();$('#scene-interior').onclick=()=>theatre?.reset();$('#scene-front').onclick=()=>theatre?.front();$('#scene-left').onclick=()=>theatre?.orbit(-Math.PI/6);$('#scene-right').onclick=()=>theatre?.orbit(Math.PI/6);$('#scene-top').onclick=()=>theatre?.top();$('#scene-zoom-in').onclick=()=>theatre?.zoom(.8);$('#scene-zoom-out').onclick=()=>theatre?.zoom(1.25);}
function sceneStats(){renderProfileCoverage();renderSceneKey();renderPowers();renderLeadership();let ct=data.counts[chamber];$('#chamber-stats').innerHTML=`<div class="statline"><span>全部席位</span><strong>${ct.total}</strong></div><div class="statline"><span>本届改选</span><strong>${ct.contested2026}</strong></div><div class="statline"><span>多数门槛</span><strong>${chamber==='senate'?'51*':'218'}</strong></div><details class="source-details"><summary>程序说明</summary><p>${chamber==='senate'?'*50–50时由副总统投关键票。':'现任选区不等于2026选举区；新候选人分别核验。'}</p></details>`;}
function fill(){let d=new Date(evidence.asOf||data.asOf);$('#asof').textContent=d.toLocaleString(getLocale(),{timeZone:'Asia/Tokyo',hour12:false})+' JST';$('#summary').innerHTML=[['当前参院党团','53 R / 47 D','含 2 名独立议员加入民主党党团'],['本届改选','35 / 435','参议院 / 众议院；含参院 2 席特别选举'],['时间序列','首版基线','缺席位历史，不推算单日胜率']].map(x=>`<article class="summary-card"><div class="eyebrow">${x[0]}</div><div class="big">${x[1]}</div><div class="small muted">${x[2]}</div></article>`).join('');const watch=['MI','OH','ME','AK','TX','IA','NC','GA','NH'];let ratings=(evidence.ratings||[]).filter(x=>x.chamber==='senate'&&watch.includes(x.state));$('#ratings').innerHTML=ratings.length?ratings.map((r,i)=>`<article class="rating-card"><div class="rating-meta"><span>${String(i+1).padStart(2,'0')} / ${esc(r.state)} SENATE</span><span>${esc(r.provider||'公开机构评级')}</span></div><h3>${esc(r.state)} <span class="muted">${esc(ratingLabel(r))}</span></h3><div class="rating-band"></div>${r.note?`<details><summary>来源详情</summary><p>${esc(r.note)}</p></details>`:''}<a class="small" target="_blank" rel="noopener" href="${esc(r.source)}">评级原文 ↗</a></article>`).join(''):'<div class="trend-blank">尚无足够的同口径评级历史，暂不生成变化排名。</div>';
let history=evidence.history||[];$('#trend').innerHTML=history.length?history.map(h=>`<div class="trend-row"><div>${esc(h.date||h.asOf)}<div class="small muted">${esc(h.metric||h.label||'泛国会投票意向')} · ${'RCP'}</div></div><strong>${esc(h.display|| (h.margin!=null?'D+'+h.margin:'待核验'))}</strong></div><details><summary>来源详情</summary><p>${esc(h.note)}</p></details>`).join(''):'<div class="trend-blank">尚无完整的连续日线。<br>从本次已核验快照建立基线，不回填虚构历史。</div>';
renderNewsImpact(evidence,esc);
const ms=[['事实与预测分层','现任归属来自国会官方名单。改选席位的颜色只表示标注机构的公开评级，既非结果，也非本站独立胜率。'],['缺数据，不补故事','灰色表示评级未知；没有同口径历史时不声称评级变化。单日民调和滚动均值变化不能被当作结构性转折。'],['民调与误差','优先高质量可能投票者样本。历史误差情景需可比原始输入；未经校准的敏感性修正不称为真实支持率，也不机械复制 2024 年误差。'],['投票与管理事件','提前投票党派登记不等于得票。诉讼申请、法院裁定与实际执行分开标注。参考来源可复核，结论随新证据修订。']];$('#methods').innerHTML=(evidence.methodology||ms.map(x=>({title:x[0],text:x[1]}))).map(x=>`<div class="method-item"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div>`).join('');let ss=[...(data.sources||[]),...(evidence.sources||[])];let seen=new Set;$('#sources').innerHTML=ss.filter(x=>!seen.has(x.url)&&seen.add(x.url)).map(s=>`<div class="source"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title||s.description||s.name||s.url)} ↗</a><small>${esc(s.sourceDate||s.date||'来源日期见原文')} · 获取于 ${esc((evidence.asOf||data.asOf).slice(0,10))}</small></div>`).join('');}
Promise.all([loadJSON('data/seats.json'),loadJSON('data/evidence.json'),loadJSON('data/powers.json'),loadJSON('data/leadership.json')]).then(([s,e,p,l])=>{data=s;evidence=e;powersData=p;leadershipData=l;fill();extras();renderPowers();renderLeadership();init3D();initExplorer();document.querySelectorAll('[data-chamber]').forEach(b=>b.onclick=()=>{chamber=b.dataset.chamber;document.querySelectorAll('[data-chamber]').forEach(x=>x.classList.toggle('active',x===b));theatre?theatre.update(chamber):fallback();theatre?.setScope(keyOnly);sceneStats();table();renderExplorer();mapView?.update(chamber,keyOnly);$('#seat-title').textContent='选择一个席位';$('#seat-detail').textContent='点击模型或使用下方列表，查看具体席位。';});$('#seat-search').oninput=table;}).catch(()=>{$('#asof').textContent='数据暂时无法读取';$('#canvas').innerHTML='<p class="trend-blank">数据加载失败，请稍后刷新。此状态不代表没有选举变化。</p>';});

function extras(){
const ratingText=r=>ratingLabel({rating:r});
const changes=document.createElement('div');changes.className='change-events';changes.innerHTML='<h3>已核验的机构评级变更</h3>'+(evidence.ratingChanges||[]).map(c=>`<a class="event-row" href="${esc(c.source)}" target="_blank" rel="noopener"><span>${esc(c.date)}</span><strong>${esc(c.state)}</strong><span>${esc(ratingText(c.before))} → ${esc(ratingText(c.after))}</span><span>↗</span></a>`).join('');$('#changes').appendChild(changes);
const summary=evidence.summary;$('#summary').innerHTML=[['RCP 参院评级总览',`${summary.senate.dem} D · ${summary.senate.tossup} 胶着 · ${summary.senate.rep} R`,'含65个不改选席；D阵营含2名独立议员'],['RCP 众院评级总览',`${summary.house.dem} D · ${summary.house.tossup} 胶着 · ${summary.house.rep} R`,'完整机构总览；不等于逐席均已映射'],['逐席评级覆盖',`${evidence.coverage.senateRatings} / ${data.counts.senate.contested2026} · ${evidence.coverage.houseRatings} / 435`,`参院改选 / 众院；众院${evidence.coverage.houseUnmappedSolid}席待逐席核验`]].map(x=>`<article class="summary-card"><div class="eyebrow">${x[0]}</div><div class="big" style="font-size:23px">${x[1]}</div><div class="small muted">${x[2]}</div></article>`).join('');
const polls=document.createElement('section');polls.innerHTML='<div class="section-top"><div><p class="eyebrow">POLLING / ORIGINAL SAMPLES</p><h2>关键原始民调</h2></div><span class="tag">不与机构评级混算</span></div><div class="ratings-grid">'+(evidence.polls||[]).map(p=>`<article class="rating-card"><div class="rating-meta">${esc(p.pollster)} / ${esc(p.state)}</div><h3>${p.dem}% D · ${p.rep}% R</h3><p>调查 ${esc(p.fieldStart)} 至 ${esc(p.fieldEnd)}<br>样本 ${p.sample} · ${esc(p.sampleType)}<br>误差 ±${p.moe} 个百分点</p><details><summary>调查方法与限制</summary><p>${esc(p.mode)}。权重：${esc(p.weighting)}。${esc(p.note)}</p></details><a class="small" href="${esc(p.source)}" target="_blank" rel="noopener">原始民调 ↗</a></article>`).join('')+'</div>';$('#evidence').before(polls);
const limits=document.createElement('details');limits.className='source-details';limits.innerHTML='<summary>覆盖详情</summary><p>'+esc(evidence.coverage.limitations.join(' '))+'</p>';$('.source-section').prepend(limits);
let hs=evidence.history.slice(-14); if(hs.length>1){let step=380/(hs.length-1),lo=Math.min(...hs.map(h=>h.margin))-.2,hi=Math.max(...hs.map(h=>h.margin))+.2,yy=h=>100-(h.margin-lo)/(hi-lo)*75;let points=hs.map((h,i)=>`${40+i*step},${yy(h)}`).join(' ');let svg=`<svg viewBox="0 0 460 145" role="img" aria-label="RCP全国泛国会票领先差快照，详细数值见下方记录"><path d="M40 110H420" stroke="#e0e5dc"/><polyline points="${points}" fill="none" stroke="#3985b0" stroke-width="2"/>${hs.map((h,i)=>`<circle cx="${40+i*step}" cy="${yy(h)}" r="4" fill="#3985b0"/><text x="${40+i*step}" y="${yy(h)-15}" text-anchor="middle" font-size="13" fill="#3985b0">D+${h.margin}</text><text x="${40+i*step}" y="133" text-anchor="middle" font-size="10" fill="#71807b">${h.date.slice(5)}</text>`).join('')}</svg><details><summary>统计口径与来源</summary><p>票差单位：百分点。纵轴为局部范围，点间线仅辅助读取；非席位趋势。</p></details>`;$('#trend').insertAdjacentHTML('afterbegin',svg);}
}

function fallback(){
const ss=data.seats.filter(s=>s.chamber===chamber).sort((a,b)=>(chamber==='senate'?Number(b.contested2026)-Number(a.contested2026):0)||({D:0,I:1,T:2,U:3,R:4}[a.currentParty||'U']-{D:0,I:1,T:2,U:3,R:4}[b.currentParty||'U'])||a.seatId.localeCompare(b.seatId));const rows=chamber==='senate'?[16,19,30,35]:[25,29,33,37,41,45,49,53,59,64];let ps=[];rows.forEach((n,k)=>{let r=chamber==='senate'?[105,140,220,255][k]:110+k*21;for(let j=0;j<n;j++){let a=Math.PI*j/(n-1);ps.push({x:400-Math.cos(a)*r,y:330-Math.sin(a)*r*.85,a,row:k});}});ps.sort((a,b)=>(chamber==='senate'?Number(a.row>=2)-Number(b.row>=2):0)||a.a-b.a||a.y-b.y);let w=chamber==='senate'?23:12;$('#canvas').innerHTML=`<svg viewBox="0 0 800 400" role="img" aria-label="无WebGL设备使用同数据交互议席示意图" style="width:100%;height:100%">${chamber==='senate'?'<path d="M220 330 A180 153 0 0 1 580 330" fill="none" stroke="#b7a16e" stroke-width="13" opacity=".6"/>':''}<path d="M338 330 A62 48 0 0 1 462 330 L462 339 L338 339Z" fill="#e9eee5"/>${ss.map((s,i)=>{let p=ps[i],c='#'+colors[party(s)].toString(16);return `<g class="svg-seat" data-svg-seat="${s.seatId}" tabindex="0" role="button" aria-label="${esc(label(s))} ${s.contested2026?esc(ratingLabel(rate(s))):'不改选'}"><rect x="${p.x-w/2}" y="${p.y-w/3+4}" width="${w}" height="${w*.75}" rx="2" fill="${c}" opacity="${s.contested2026?.08:.25}"/><rect x="${p.x-w/2}" y="${p.y-w/3}" width="${w}" height="${w*.75}" rx="2" fill="white" stroke="${c}" stroke-width="1.5" stroke-opacity="${chamber==='house'?.3:1}" ${s.contested2026?'stroke-dasharray="3 2"':''}/><path d="M${p.x-w/2},${p.y-w/3}h${w}" stroke="${c}" stroke-width="3" opacity=".6"/></g>`}).join('')}<text x="400" y="383" font-size="10" text-anchor="middle" fill="#87958b">2D 兼容模式 · 相同数据，可点击查看席位</text></svg>`;document.querySelectorAll('[data-svg-seat]').forEach(el=>{el.style.opacity=keyOnly&&!isKeySeat(ss.find(s=>s.seatId===el.dataset.svgSeat),evidence)?'.06':'1';const hidden=keyOnly&&!isKeySeat(ss.find(s=>s.seatId===el.dataset.svgSeat),evidence);el.toggleAttribute('hidden',hidden);el.setAttribute('tabindex',hidden?'-1':'0');const fn=()=>{let seat=ss.find(s=>s.seatId===el.dataset.svgSeat);show(seat);openProfile(seat);};el.onclick=fn;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}};});let ct=data.counts[chamber];$('#chamber-stats').innerHTML=`<div class="statline"><span>全部席位</span><strong>${ct.total}</strong></div><div class="statline"><span>本届改选</span><strong>${ct.contested2026}</strong></div><div class="statline"><span>多数门槛</span><strong>${chamber==='senate'?'51*':'218'}</strong></div><p class="small muted">${chamber==='senate'?'* 50–50 时由副总统投关键票；党团归属与登记党籍分开。':'现任选区记录不等于2026候选人表；部分州区划已改变。'}</p>`;
}

async function loadProfiles(){for(const f of ['senate_profiles','house_profiles']){try{const j=await loadJSON('data/'+f+'.json');profileData.push(...j.profiles.map(p=>({...p,profileAsOf:j.asOf})));}catch{}}renderProfileCoverage();}loadProfiles();
function openProfile(s){const panel=$('#profile-drawer'),profile=profileData.find(x=>x.seatId===s.seatId);$('#profile-body').innerHTML=profileHTML(s,profile,esc,label);installImageFallbacks(panel);panel.classList.add('open');$('#profile-scrim').hidden=false;$('#profile-close').focus();}
function renderProfileCoverage(){if(!data||!profileData.length)return;let panel=$('#profile-coverage');if(!panel){panel=document.createElement('section');panel.id='profile-coverage';$('#leadership-panel').after(panel);}panel.innerHTML=coverageHTML(data.seats,profileData,chamber,esc);$('#download-profile-audit').onclick=()=>{const audit=coverageAudit(data.seats,profileData,chamber),blob=new Blob([JSON.stringify(audit,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='candidate-coverage-'+chamber+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
function renderSceneKey(){let key=$('#scene-material-key');if(!key){key=document.createElement('div');key.id='scene-material-key';$('.scene-controls').after(key);}const ss=data.seats.filter(s=>s.chamber===chamber),probabilities=ss.filter(s=>verifiedProbability(s)).length;key.innerHTML=`<span><i class="holo-key"></i>改选全息虚影 ${ss.filter(s=>s.contested2026).length}</span><span><i class="solid-key"></i>不改选实体 ${ss.filter(s=>!s.contested2026&&!s.vacant).length}</span>`;}

function closeProfile(){$('#profile-drawer').classList.remove('open');$('#profile-scrim').hidden=true;}$('#profile-close').onclick=closeProfile;$('#profile-scrim').onclick=closeProfile;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile();});

document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!$('#profile-drawer').classList.contains('open'))return;const fs=[...$('#profile-drawer').querySelectorAll('button,a[href],input')];const first=fs[0],last=fs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});

function renderPowers(){$('#seat-zones').innerHTML=chamber==='senate'?'<span>前区 · 本届改选 35</span><span>金色宽过道分隔</span><span>后区 · 本届不改选 65</span>':'<span>众议院 435 席 · 本届全部改选</span><span>无不改选保留区 · 点击席位聚焦</span>';if(!powersData)return;let ids=meaningfulPowers(powersData,chamber).map(p=>p.id);$('#power-panel').innerHTML=`<div class="power-heading"><div><span class="eyebrow">POWER & PROCEDURE</span><h3>席位分布与权力门槛</h3></div></div><div class="power-segments" data-count="${ids.length}" role="tablist" aria-label="选择议会程序">${ids.map(id=>{let p=powersData.powers.find(x=>x.id===id);return `<button role="tab" id="power-tab-${id}" data-power="${id}" aria-selected="${id===selectedPower}" aria-controls="power-content" tabindex="${id===selectedPower?0:-1}" title="${esc(p.labelZh)}">${powerIcon(id)}<span>${esc(powerShort(id))}</span></button>`;}).join('')}</div><div id="power-content" role="tabpanel"></div>`;const tabs=[...document.querySelectorAll('[data-power]')];if(!ids.includes(selectedPower))selectedPower='ordinary_passage';const choose=(id,focus=false)=>{selectedPower=id;tabs.forEach(b=>{let active=b.dataset.power===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();});renderPowerContent();};tabs.forEach((b,i)=>{b.onclick=()=>choose(b.dataset.power);b.onkeydown=e=>{let next=e.key==='ArrowRight'?(i+1)%tabs.length:e.key==='ArrowLeft'?(i+tabs.length-1)%tabs.length:e.key==='Home'?0:e.key==='End'?tabs.length-1:null;if(next!==null){e.preventDefault();choose(tabs[next].dataset.power,true);}};});choose(selectedPower); }
let thresholdSide='D';
function renderPowerContent(){const p=powersData.powers.find(x=>x.id===selectedPower);$('#power-content').setAttribute('aria-labelledby','power-tab-'+selectedPower);$('#power-content').innerHTML=comparisonHTML(data,evidence,chamber,p,esc,thresholdSide)+`<details class="power-rule"><summary>${esc(p.labelZh)} · ${esc(p.shortLabelZh)}</summary><p>${esc(p.rule)}</p><p class="small muted">${esc((p.caveats||[]).join(' '))}</p><p class="small">${p.source.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)} ↗</a>`).join(' · ')}</p></details><details class="power-rule"><summary>基础程序与来源</summary>${powersData.powers.filter(x=>!x.gauge?.showSeatLine).map(x=>`<p><strong>${esc(x.labelZh)}</strong> · ${esc(x.rule)}</p><p>${x.source.map(y=>`<a href="${esc(y.url)}" target="_blank" rel="noopener">${esc(y.title)} ↗</a>`).join(' · ')}</p>`).join('')}</details><details class="power-rule"><summary>程序说明</summary><p class="small muted">党派席位不是实际赞成票；跨党投票、出席、程序及总统阶段均影响结果。无统一“重大议案”门槛。核验于 ${esc(powersData.verifiedAt)}。</p></details>`;document.querySelectorAll('[data-threshold-side]').forEach(b=>b.onclick=()=>{thresholdSide=b.dataset.thresholdSide;renderPowerContent();});}
function renderLeadership(){if(!leadershipData)return;let c=leadershipData[chamber],items=[c.podium,...(c.scenarios||c.partyLeadershipScenarios||[])];$('#leadership-panel').innerHTML=`<p class="eyebrow">PRESIDING OFFICER & CONDITIONAL SCENARIOS</p><div class="leader-grid">${items.map((x,i)=>{let p=leadershipData.persons.find(p=>p.id===x.personId);return `<button class="leader-card ${i?'conditional':''}" data-leader="${i}"><small>${esc(x.label)}</small><strong>${esc((getLocale()==='zh-CN'?p.nameZh:p.name))}</strong><span>${i?'虚线：条件情景，尚未当选':esc(p.currentRole)}</span></button>`;}).join('')}</div><details class="source-details"><summary>职务与情景来源</summary><p>${esc(c.notes[0])}</p></details>`;$('#leadership-panel').querySelectorAll('[data-leader]').forEach(b=>b.onclick=()=>showLeader(items[Number(b.dataset.leader)]));}
function showLeader(entry){let p=leadershipData.persons.find(p=>p.id===entry.personId);$('#profile-body').innerHTML=`<p class="eyebrow">${entry.render==='dashed'?'条件情景 / 不是选举结果':'已核验现任职务'}</p><section class="person-id"><div class="person-portrait"><span>${esc(p.name.split(' ').map(x=>x[0]).join(''))}</span></div><div><h2>${esc((getLocale()==='zh-CN'?p.nameZh:p.name))}</h2><p>${esc(p.name)}</p><span class="profile-badge">${esc(names[p.party])}</span></div></section><h3>${esc(entry.label)}</h3><p>${esc(p.currentRole)}</p><p>${esc(entry.condition||entry.note||'现任职务示意，不表示此刻正在主持会议。')}</p><p>${esc(entry.possibleRole||'')}</p><a href="${esc(entry.source||p.source)}" target="_blank" rel="noopener">官方与情景依据 ↗</a><p class="small muted">人偶为抽象示意，不模拟本人相貌。不提供人选胜率。资料截至 ${esc(leadershipData.asOf)}。</p>`;$('#profile-drawer').classList.add('open');$('#profile-scrim').hidden=false;$('#profile-close').focus();}

const powerSymbols={bill_introduction:'M6 3h12v18H6z M9 8h6 M12 5v6 M9 15h6',ordinary_passage:'M4 12l5 5L20 6',speaker_election:'M5 19h14 M7 19v-6h10v6 M12 4v6 M9 7h6',legislative_cloture:'M5 5h14v11H9l-4 4z M9 9h6 M9 12h4',reconciliation:'M4 6h16v14H4z M8 3v6 M16 3v6 M8 13h8 M8 16h5',nominations:'M12 3a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M5 21v-3a7 7 0 0 1 14 0v3',veto_override:'M7 8h10a5 5 0 0 1 0 10H9 M7 4L3 8l4 4',impeachment_house:'M4 20h16 M7 16V9 M12 16V9 M17 16V9 M3 7l9-4 9 4z',impeachment_conviction:'M5 20h10 M12 4l7 7 M9 7l7 7 M6 17l8-8',treaty_consent:'M3 7l6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 4v15 M15 7v15',constitutional_amendment:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h3',house_suspension:'M5 4v16 M10 4v16 M15 8l6 4-6 4z'};
function powerIcon(id){return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${powerSymbols[id]||powerSymbols.ordinary_passage}"/></svg>`;}
function powerShort(id){const labels={zh:['提交法案','最终通过','议长选举','终结辩论','预算协调','提名确认','否决覆议','弹劾指控','弹劾定罪','条约批准','宪法修正','快速程序'],en:['Introduce','Passage','Speaker','End debate','Reconciliation','Confirm','Override veto','Impeach','Convict','Treaties','Amendment','Fast-track'],fr:['Déposer','Adoption','Présidence','Clôture','Budget','Confirmer','Passer le veto','Mise en accusation','Condamner','Traités','Amendement','Procédure rapide'],es:['Presentar','Aprobar','Presidencia','Cerrar debate','Presupuesto','Confirmar','Superar veto','Acusar','Condenar','Tratados','Enmienda','Vía rápida'],ja:['法案提出','最終可決','議長選出','討論終結','予算調整','指名承認','拒否権覆し','弾劾訴追','弾劾有罪','条約承認','憲法修正','迅速手続']},ids=Object.keys(powerSymbols),lang=getLocale().split('-')[0];return labels[lang][ids.indexOf(id)]||id;}
window.addEventListener('localechange',()=>{if(data){renderPowers();if($('#floor-summary'))renderExplorer();$('#asof').textContent=new Date(evidence.asOf||data.asOf).toLocaleString(getLocale(),{timeZone:'Asia/Tokyo',hour12:false})+' JST';renderLeadership();}});

function renderExplorer(){
 const model=explorerModel(data,evidence,chamber),lead=floorLead(model);$('#key-seat-summary').innerHTML=keyOnly?compactKeyHTML(model,esc):'';
 $('#floor-summary').innerHTML=`<h4>全院评级构成 <span>${lead.seats?lead.side+' +'+lead.seats+' · ':''}中点 50%</span></h4><div class="floor-counts">${model.outlook.segments.map(s=>`<span><i style="background:${segmentColor(s)}"></i>${s.alignment==='T'||s.alignment==='U'?'':s.alignment+' · '}${esc(categoryLabels[s.kind])}${s.independent?' · 独立议员':''} <b>${s.count}</b></span>`).join('')}</div><details class="source-details"><summary>扇形图口径</summary><p>扇形角度＝该类别席位数÷全院席位数。中央指针固定为50%中点；外弧表示两方已归类席位差额，不是胜率。胶着与未知不分摊。</p><p>全院多数参考 ${model.majority} / ${model.capacity} · ${chamber==='senate'?'50–50时副总统投关键票，不增加参院席位。':''}</p></details>`;
 document.querySelectorAll('[data-seat-scope]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.seatScope==='key')===keyOnly)));
}
function initExplorer(){
 const panel=document.createElement('div');panel.className='explorer-toolbar';panel.innerHTML='<div role="group" aria-label="展示视图"><button data-scene-view="chamber" aria-pressed="true">议事厅</button><button data-scene-view="map" aria-pressed="false">州地图</button></div><div role="group" aria-label="席位范围"><button data-seat-scope="all" aria-pressed="true">全体席位</button><button data-seat-scope="key" aria-pressed="false">关键席位</button></div>';$('.chamber-layout').before(panel);
 const key=document.createElement('div');key.id='key-seat-summary';panel.after(key);
 const floor=document.createElement('div');floor.id='floor-summary';$('.scene-controls').after(floor);
 const map=document.createElement('div');map.id='state-map';map.hidden=true;$('.chamber-layout').after(map);
 panel.querySelectorAll('[data-seat-scope]').forEach(b=>b.onclick=()=>{keyOnly=b.dataset.seatScope==='key';theatre?theatre.setScope(keyOnly):fallback();table();renderExplorer();mapView?.update(chamber,keyOnly);});
 panel.querySelectorAll('[data-scene-view]').forEach(b=>b.onclick=async()=>{activeSceneView=b.dataset.sceneView;panel.querySelectorAll('[data-scene-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('.chamber-layout').hidden=activeSceneView!=='chamber';map.hidden=activeSceneView!=='map';theatre?.setActive(activeSceneView==='chamber');if(activeSceneView==='map'&&!mapPending){map.innerHTML='<p>地图加载中</p>';mapPending=createStateMap(map,{roster:data,evidence,chamber,esc,onSeat:s=>{show(s);openProfile(s);}}).then(m=>{mapView=m;m.update(chamber,keyOnly);}).catch(()=>{map.innerHTML='<p>地图暂时无法读取，请刷新重试。</p>';mapPending=null;});} });renderExplorer();
}
